`,e.jsxs(a.p,{children:["Nos últimos dois anos, a legislação aplicada aos meios de hospedagem passou por atualizações relevantes. Entre as principais mudanças estão a ",e.jsx(a.a,{href:"https://www.gov.br/turismo/pt-br/centrais-de-conteudo-/publicacoes/atos-normativos-2/2025/portaria-mtur-no-28-de-16-de-setembro-de-2025?utm_source=chatgpt.com",children:"Portaria MTur nº 28/2025"}),", que regulamentou os procedimentos de entrada e saída de hóspedes e reafirmou que a diária corresponde a ",e.jsx(a.strong,{children:"24 horas"}),", e a ",e.jsx(a.a,{href:"https://www.gov.br/turismo/pt-br/centrais-de-conteudo-/publicacoes/atos-normativos-2/2025/portaria-mtur-no-41-de-14-de-novembro-de-2025?utm_source=chatgpt.com",children:"Portaria MTur nº 41/2025"}),", que instituiu a ",e.jsx(a.strong,{children:"FNRH em meio digital"}),"."]}),`
