`,e.jsx(a.p,{children:"Além do cadastro no Cadastur, os meios de hospedagem devem fornecer ao Ministério do Turismo informações relacionadas ao perfil dos hóspedes e à ocupação do empreendimento. Entre os dados exigidos estão elementos como nacionalidade, quantitativo de hóspedes, taxa de ocupação, permanência média e número de hóspedes por unidade habitacional."}),`
`,e.jsxs(a.p,{children:["Essas informações se conectam à ",e.jsx(a.strong,{children:"Ficha Nacional de Registro de Hóspedes (FNRH)"}),", ao ",e.jsx(a.strong,{children:"Boletim de Ocupação Hoteleira (BOH)"})," e ao ",e.jsx(a.strong,{children:"Sistema Nacional de Registro de Hóspedes (SNRHos)"}),"."]}),`
