`,e.jsxs(a.p,{children:["A ",e.jsx(a.a,{href:"https://www.gov.br/turismo/pt-br/centrais-de-conteudo-/publicacoes/atos-normativos-2/2025/portaria-mtur-no-41-de-14-de-novembro-de-2025?utm_source=chatgpt.com",children:"Portaria MTur nº 41/2025"})," instituiu a ",e.jsx(a.strong,{children:"FNRH em meio digital"}),", em substituição à ficha em papel, por meio da Plataforma FNRH Digital. Depois, a ",e.jsx(a.a,{href:"https://www.gov.br/turismo/pt-br/centrais-de-conteudo-/publicacoes/atos-normativos-2/2026/portaria-mtur-no-4-de-18-de-fevereiro-de-2026?utm_source=chatgpt.com",children:"Portaria MTur nº 4/2026"})," alterou a vigência da medida, e o Ministério do Turismo informou que os meios de hospedagem têm até ",e.jsx(a.strong,{children:"20 de abril de 2026"})," para se adequar."]}),`
