`,e.jsx(a.p,{children:"Por isso, acompanhar a legislação não deve ser visto como burocracia isolada, mas como parte da gestão preventiva do negócio."}),`
`,e.jsx(a.h2,{id:"fiscalização-dos-meios-de-hospedagem",children:e.jsx(a.strong,{children:"Fiscalização dos meios de hospedagem"})}),`
